interface.definition:
a!localVariables(
  local!isNewVersion: if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    true,
    if(
      todatetime(ri!nomination.createdOn) > #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12333392",
      true,
      false
    )
  ),
  local!date: now(),
  local!addedDoc,

  local!docId: ri!appianDueDiligenceDoc,
  local!userGroup: #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12422687",
  #"SYSTEM_SYSRULES_sectionLayout_v1"(
    label: "Uploaded Attachments",
    labelColor: "SECONDARY",
    contents: {
      #"SYSTEM_SYSRULES_richTextDisplayField"(
        labelPosition: "COLLAPSED",
        value: {
          #"SYSTEM_SYSRULES_richTextItem_v1"(text: "", size: "SMALL", style: "EMPHASIS")
        }
      ),
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: {
          #"SYSTEM_SYSRULES_richTextDisplayField"(
            value: {
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: "Please Upload Attachments Here",
                style: "STRONG"
              )
            }
          ),
          #"SYSTEM_SYSRULES_fileUploadField_v1"(
            target: #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12419091",
            value: local!docId,
            saveInto: {
              local!docId,
              a!save(local!addedDoc,
              difference(
                tointeger(save!value),
                tointeger(ri!appianDueDiligenceDoc)
              )
              ),
              a!save(
                ri!dueDiligenceDocumentsToDelete,
                difference(
                  tointeger(ri!appianDueDiligenceDoc),
                  tointeger(save!value)
                )
              ),
              if(
                #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!dueDiligenceDocument),
                null,
                a!save(
                  ri!dueDiligenceDocument,
                  remove(
                    ri!dueDiligenceDocument,
                    wherecontains(
                      difference(
                        tointeger(
                          property(
                            index(
                              ri!dueDiligenceDocument,
                              wherecontains(
                                tointeger(null),
                                tointeger(
                                  property(ri!dueDiligenceDocument, "documentId", null)
                                )
                              ),
                              null
                            ),
                            "docId",
                            null
                          )
                        ),
                        tointeger(local!addedDoc)
                      ),
                      tointeger(property(ri!dueDiligenceDocument, "docId", null))
                    )
                  )
                )
              ),
              a!save(
                ri!dueDiligenceDocument,
                if(
                  a!isNullOrEmpty(local!addedDoc),
                  ri!dueDiligenceDocument,
                append(
                  ri!dueDiligenceDocument,
                  #"SYSTEM_SYSRULES_forEach"(
                    items: local!addedDoc,
                    expression: 'type!{urn:com:appian:types:CAW}CAW_Document'(
                      documentId: null,
                      moduleId: ri!moduleId,
                      requestId: ri!requestId,
                      taskId: ri!taskId,
                      docId: tointeger(fv!item),
                      version: ri!version,
                      isActive: true,
                      isLocked: false,
                      is_DueDiligenceDoc: true,
                      createdBy: loggedInUser(),
                      createdOn: local!date,
                      modifiedBy: loggedInUser(),
                      modifiedOn: local!date
                    )
                  )
                )
                )
              ),
              a!save(
                ri!dueDiligenceDocument,
                union(
                  ri!dueDiligenceDocument,
                  ri!dueDiligenceDocument
                )
              )
            },
            disabled: not(
              isusermemberofgroups(loggedInUser(), local!userGroup)
            )
          )
        }
      )
    },
    showWhen: local!isNewVersion,
    isCollapsible: true,
    divider: "ABOVE",
    dividerWeight: "THIN",
    marginBelow: "STANDARD"
  )
)
